/// Public brand artwork that is not practical to express as a single monochrome SVG path.
///
/// Keep this embedded: the hand-built app bundle does not copy SwiftPM resource bundles, and a
/// provider mark must never depend on the network at runtime. The source is recorded on the Mark.
enum ProviderOfficialImageData {
    static let feishuPNGBase64 = ""
    static let slackPNGBase64 = ""
    static let appStoreConnectPNGBase64 = ""
    static let awsPNGBase64 = ""
}
